import test from 'node:test';
import assert from 'node:assert/strict';
import {createSplusCombat} from '../src/domain/combat/splus-mechanics.mjs';
import {SPLUS_EXTRA_BY_ID, resolveSplusExtraId} from '../src/domain/hero/splus-extras.mjs';
const H=(key,team=1,slot=0,extra={})=>({id:`${team}:${key}`,sourceId:`hero_splus_${key}`,team,slot,hp:1e6,maxHp:1e6,atk:1000,def:200,speed:100,energy:100,crit:0,accuracy:100,statuses:[],...extra});
const make=units=>{const e=createSplusCombat({units,rng:()=>.5});e.start();return e;};
const hits=(e,src,tgt,action)=>e.events.filter(x=>x.type==='damage'&&x.sourceId===src&&x.targetId===tgt&&x.action===action&&!x.secondary);

test("Lăng Chân: registered as an S+ extra and resolvable by key / slug",()=>{
  assert.ok(SPLUS_EXTRA_BY_ID.hero_splus_lang_chan);
  for(const alias of ["lang_chan","lang-chan","hero_splus_lang_chan"])assert.equal(resolveSplusExtraId(alias),'hero_splus_lang_chan',alias);
});

test("Lăng Chân basic: 1 hit(s), one target",()=>{
  const e=make([H('lang_chan',1,0),H('a',2,0),H('b',2,1)]);
  e.act('1:lang_chan','basic','2:a');
  assert.equal(hits(e,'1:lang_chan','2:a','basic').length,1);
  assert.equal(hits(e,'1:lang_chan','2:b','basic').length,0);
});

test("Lăng Chân ultimate: 1 hit(s), every enemy",()=>{
  const e=make([H('lang_chan',1,0),H('a',2,0),H('b',2,1)]);
  e.act('1:lang_chan','ultimate','2:a');
  assert.equal(hits(e,'1:lang_chan','2:a','ultimate').length,1);
  assert.equal(hits(e,'1:lang_chan','2:b','ultimate').length,1);
});

